<script setup lang="ts">import {ref,onMounted} from 'vue';import {go} from '../router';import {cases} from '../stores/cases';import {revisions} from '../stores/revisions';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),revision=ref('demo-revision'),target=ref('Fault'),evidence=ref('{"Heat":1,"Alarm":1}'),candidates=ref('null');const {error,busy,act}=useTask();onMounted(()=>Promise.all([cases.load(),revisions.load()]));function submit(){act(async()=>{await cases.create({name:name.value,revision_id:revision.value,target:target.value,evidence_json:evidence.value,candidates_json:candidates.value});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({case_id:id});go('/results?run='+r.id)})}</script><template><PageHeading index="03 / 证据案例" title="证据不是结论，查询目标单独锁定。" note="证据为节点0/1映射。候选null表示所有未观测非目标节点，或传入不重复节点数组；查询已观测仍须检查证据可行性。"/><Notice :message="error"/><div class="two-col"><section><article v-for="c in cases.items.value" :key="c.id" class="case-row"><p class="eyebrow">LOCKED EVIDENCE CASE</p><h2>{{c.name}}</h2><p>查询 {{c.target}} · 证据 {{JSON.stringify(c.evidence)}}<br>候选 {{c.candidates.join(', ')||'无'}}</p><button v-if="canWrite()" :disabled="busy" @click="execute(c.id)">执行后台概率推理 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建证据案例</h2><label>案例名称<input v-model="name" required minlength="2"></label><label>CPT版本<select v-model="revision"><option v-for="r in revisions.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>查询节点ID<input v-model="target" required></label><label>证据JSON<textarea v-model="evidence" rows="4" required></textarea></label><label>候选JSON / null或数组<textarea v-model="candidates" rows="3" required></textarea></label><button :disabled="busy">保存证据案例</button></form></div></template>
